async function checkIfUserPaid({
  context,
  lnPayment,
}: {
  context: any;
  lnPayment?: LnPayment;
}) {
  if (
    !context.user.hasPaid &&
    !context.user.credits &&
    !context.user.isUsingLn
  ) {
    throw new HttpError(402, "User must pay to continue");
  }
  if (context.user.subscriptionStatus === "past_due") {
    throw new HttpError(
      402,
      "Your subscription is past due. Please update your payment method."
    );
  }
  if (context.user.isUsingLn) {
    let invoiceStatus;
    if (lnPayment) {
      const lnPaymentInDB = await context.entities.LnPayment.findUnique({
        where: {
          pr: lnPayment.pr,
        },
      });
      invoiceStatus = lnPaymentInDB?.status;
    }
    console.table({ lnPayment, invoiceStatus });
    if (invoiceStatus !== "success") {
      throw new HttpError(402, "Your lightning payment has not been paid");
    }
  }
}

function isClaudeModel(model: string): boolean {
  return model.startsWith("claude-");
}

function getModelForProvider(gptModel: string): string {
  console.log("🔍 Original model from frontend:", gptModel);

  // Map frontend model names to actual API model names
  if (gptModel === "gpt-5") {
    console.log("📍 Mapping gpt-5 to gpt-4o");
    return "gpt-4o"; // Use best available OpenAI model until GPT-5 is released
  }
  if (gptModel === "claude-sonnet-4.1") {
    console.log("📍 Mapping claude-sonnet-4.1 to claude-sonnet-4-20250514");
    return "claude-sonnet-4-20250514"; // Claude Sonnet 4
  }

  // Add fallback for Claude models
  if (gptModel.startsWith("claude-") && !gptModel.includes("-20")) {
    // If no date specified, use current model names
    if (gptModel === "claude-3-5-sonnet" || gptModel === "claude-sonnet-3.5") {
      console.log("📍 Mapping", gptModel, "to claude-3-5-sonnet-20241022");
      return "claude-3-5-sonnet-20241022";
    }
    if (gptModel === "claude-3-5-haiku" || gptModel === "claude-haiku-3.5") {
      console.log("📍 Mapping", gptModel, "to claude-3-5-haiku-20241022");
      return "claude-3-5-haiku-20241022";
    }
    if (gptModel === "claude-sonnet-4" || gptModel === "claude-4-sonnet") {
      console.log("📍 Mapping", gptModel, "to claude-sonnet-4-20250514");
      return "claude-sonnet-4-20250514";
    }
    if (gptModel === "claude-opus-4" || gptModel === "claude-4-opus") {
      console.log("📍 Mapping", gptModel, "to claude-opus-4-20250514");
      return "claude-opus-4-20250514";
    }
  }

  console.log("📍 No mapping found, using original model:", gptModel);
  return gptModel;
}

async function callOpenAI(payload: any): Promise<OpenAIResponse> {
  const response = await fetch("https://api.openai.com/v1/chat/completions", {
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${process.env.OPENAI_API_KEY!}`,
    },
    method: "POST",
    body: JSON.stringify(payload),
  });

  return (await response.json()) as OpenAIResponse;
}

async function callClaude(
  messages: any[],
  temperature: number,
  model: string
): Promise<{ content: string; tokens: number }> {
  if (!anthropic) {
    throw new HttpError(
      500,
      "ANTHROPIC_API_KEY environment variable is not set"
    );
  }

  // Extract system message and user messages for Claude format
  const systemMessage =
    messages.find((m) => m.role === "system")?.content || "";
  const userMessages = messages.filter((m) => m.role !== "system");

  try {
    const response = await anthropic.messages.create({
      model: model,
      max_tokens: 4000,
      temperature: temperature,
      system: systemMessage,
      messages: userMessages,
    });

    if (!response.content || response.content.length === 0) {
      throw new HttpError(500, "Claude returned an empty response");
    }

    const textContent = response.content.find((block) => block.type === "text");
    if (!textContent || !textContent.text) {
      throw new HttpError(500, "No text content found in Claude response");
    }

    return {
      content: textContent.text,
      tokens: response.usage?.output_tokens || 0,
    };
  } catch (error: any) {
    console.error("Claude API Error:", error);

    // Handle specific Anthropic errors
    if (error.status === 401) {
      throw new HttpError(401, "Invalid Anthropic API key");
    } else if (error.status === 429) {
      throw new HttpError(
        429,
        "Claude API rate limit exceeded. Please try again later."
      );
    } else if (error.status >= 500) {
      throw new HttpError(500, `Claude API server error: ${error.message}`);
    } else {
      throw new HttpError(
        500,
        `Claude API error: ${error.message || "Unknown error"}`
      );
    }
  }
}

// Helper function to create or get Stripe customer
async function getOrCreateStripeCustomer(
  email: string
): Promise<Stripe.Customer> {
  const existingCustomers = await stripe.customers.list({
    email: email,
    limit: 1,
  });

  if (existingCustomers.data.length > 0) {
    console.log("Using existing Stripe customer");
    return existingCustomers.data[0];
  }

  console.log("Creating new Stripe customer");
  return await stripe.customers.create({
    email: email,
  });
}

// Helper function to create or get Stripe product and price
async function getOrCreatePriceId(
  planType: string,
  duration: string
): Promise<string> {
  const config =
    PRICING_CONFIG[planType as keyof typeof PRICING_CONFIG][
      duration as keyof (typeof PRICING_CONFIG)["cover-letter"]
    ];

  // Create product if it doesn't exist
  const productId = `${planType}-${duration}`;
  let product: Stripe.Product;

  try {
    product = await stripe.products.retrieve(productId);
  } catch (error) {
    product = await stripe.products.create({
      id: productId,
      name: `CoverLetterGPT - ${
        planType === "cover-letter" ? "Cover Letters Only" : "Full Suite"
      } (${duration})`,
      description:
        planType === "cover-letter"
          ? "Unlimited cover letter generation with Claude AI"
          : "Unlimited cover letters + resume generation with Claude AI",
    });
  }

  // Create price if it doesn't exist
  const priceId = `price-${planType}-${duration}`;
  try {
    const existingPrice = await stripe.prices.retrieve(priceId);
    return existingPrice.id;
  } catch (error) {
    const newPrice = await stripe.prices.create({
      product: product.id,
      unit_amount: config.amount,
      currency: "usd",
      recurring: {
        interval: config.interval as "week" | "month" | "year",
      },
    });
    return newPrice.id;
  }
}

export const generateCoverLetter: GenerateCoverLetter<
  CoverLetterPayload,
  CoverLetter
> = async (
  {
    jobId,
    title,
    content,
    description,
    isCompleteCoverLetter,
    includeWittyRemark,
    temperature,
    gptModel,
    lnPayment,
  },
  context
) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  await checkIfUserPaid({ context, lnPayment });

  let command;
  if (isCompleteCoverLetter) {
    command = includeWittyRemark
      ? gptConfig.coverLetterWithAWittyRemark
      : gptConfig.completeCoverLetter;
  } else {
    command = gptConfig.ideasForCoverLetter;
  }

  console.log("AI model received:", gptModel);

  const actualModel = getModelForProvider(gptModel);
  const isUsingClaude = isClaudeModel(gptModel);

  console.log("Mapped to actual model:", actualModel);
  console.log("Is using Claude:", isUsingClaude);

  // Check if Claude is requested but not available
  if (isUsingClaude && !anthropic) {
    throw new HttpError(
      500,
      "Claude models are not available. Please configure ANTHROPIC_API_KEY or choose an OpenAI model."
    );
  }

  const messages = [
    {
      role: "system",
      content: command,
    },
    {
      role: "user",
      content: `My Resume: ${content}. Job title: ${title} Job Description: ${description}.`,
    },
  ];

  try {
    if (
      !context.user.hasPaid &&
      !context.user.credits &&
      !context.user.isUsingLn
    ) {
      throw new HttpError(402, "User has not paid or is out of credits");
    } else if (context.user.credits && !context.user.hasPaid) {
      console.log("decrementing credits \n\n");
      await context.entities.User.update({
        where: { id: context.user.id },
        data: {
          credits: {
            decrement: 1,
          },
        },
      });
    }

    let responseContent: string;
    let tokenUsage: number;

    if (isUsingClaude) {
      const claudeResponse = await callClaude(
        messages,
        temperature,
        actualModel
      );
      responseContent = claudeResponse.content;
      tokenUsage = claudeResponse.tokens;
    } else {
      const openaiPayload = {
        model: actualModel,
        messages,
        temperature,
      };

      const openaiResponse = await callOpenAI(openaiPayload);

      if (openaiResponse?.error) {
        throw new HttpError(
          500,
          openaiResponse?.error?.message ||
            "Something went wrong with OpenAI API"
        );
      }

      responseContent = openaiResponse.choices[0].message.content;
      tokenUsage = openaiResponse.usage.completion_tokens;
    }

    if (!responseContent || responseContent.trim().length === 0) {
      throw new HttpError(500, "AI returned an empty response");
    }

    return context.entities.CoverLetter.create({
      data: {
        title,
        content: responseContent,
        tokenUsage,
        user: { connect: { id: context.user.id } },
        job: { connect: { id: jobId } },
      },
    });
  } catch (error: any) {
    if (!context.user.hasPaid && error?.statusCode != 402) {
      await context.entities.User.update({
        where: { id: context.user.id },
        data: {
          credits: {
            increment: 1,
          },
        },
      });
    }
    console.error(error);
    throw new HttpError(
      error.statusCode || 500,
      error.message || "Something went wrong"
    );
  }
};

export const generateEdit: GenerateEdit<
  { content: string; improvement: string; lnPayment?: LnPayment },
  string
> = async ({ content, improvement, lnPayment }, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  await checkIfUserPaid({ context, lnPayment });

  let command;
  command = `You are a cover letter editor. You will be given a piece of isolated text from within a cover letter and told how you can improve it. Only respond with the revision. Make sure the revision is in the same language as the given isolated text.`;

  // Determine which model to use - default to a fast model for edits
  const gptModel =
    context.user.gptModel === "gpt-4" || context.user.gptModel === "gpt-4o"
      ? "gpt-4o"
      : "gpt-4o-mini";
  const isUsingClaude = isClaudeModel(gptModel);
  const actualModel = getModelForProvider(gptModel);

  // Check if Claude is requested but not available
  if (isUsingClaude && !anthropic) {
    throw new HttpError(
      500,
      "Claude models are not available. Please configure ANTHROPIC_API_KEY or choose an OpenAI model."
    );
  }

  const messages = [
    {
      role: "system",
      content: command,
    },
    {
      role: "user",
      content: `Isolated text from within cover letter: ${content}. It should be improved by making it more: ${improvement}`,
    },
  ];

  try {
    if (
      !context.user.hasPaid &&
      !context.user.credits &&
      !context.user.isUsingLn
    ) {
      throw new HttpError(402, "User has not paid or is out of credits");
    } else if (context.user.credits && !context.user.hasPaid) {
      console.log("decrementing credits \n\n");
      await context.entities.User.update({
        where: { id: context.user.id },
        data: {
          credits: {
            decrement: 1,
          },
        },
      });
    }

    let responseContent: string;

    if (isUsingClaude) {
      const claudeResponse = await callClaude(messages, 0.5, actualModel);
      responseContent = claudeResponse.content;
    } else {
      const openaiPayload = {
        model: actualModel,
        messages,
        temperature: 0.5,
      };

      const openaiResponse = await callOpenAI(openaiPayload);

      if (openaiResponse?.error) {
        throw new HttpError(
          500,
          openaiResponse?.error?.message ||
            "Something went wrong with OpenAI API"
        );
      }

      responseContent = openaiResponse.choices[0].message.content;
    }

    if (responseContent && responseContent.length > 0) {
      return responseContent;
    } else {
      throw new HttpError(500, "AI returned an empty response");
    }
  } catch (error: any) {
    if (!context.user.hasPaid && error?.statusCode != 402) {
      await context.entities.User.update({
        where: { id: context.user.id },
        data: {
          credits: {
            increment: 1,
          },
        },
      });
    }
    console.error(error);
    throw new HttpError(
      error.statusCode || 500,
      error.message || "Something went wrong"
    );
  }
};

export type JobPayload = Pick<
  Job,
  "title" | "company" | "location" | "description"
>;

export const createJob: CreateJob<JobPayload, Job> = (
  { title, company, location, description },
  context
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.Job.create({
    data: {
      title,
      description,
      location,
      company,
      user: { connect: { id: context.user.id } },
    },
  });
};

