export type UpdateCoverLetterPayload = Pick<Job, "id" | "description"> &
  Pick<CoverLetter, "content"> & {
    isCompleteCoverLetter: boolean;
    includeWittyRemark: boolean;
    temperature: number;
    gptModel: string;
    lnPayment?: LnPayment;
  };

export const updateCoverLetter: UpdateCoverLetter<
  UpdateCoverLetterPayload,
  string
> = async (
  {
    id,
    description,
    content,
    isCompleteCoverLetter,
    includeWittyRemark,
    temperature,
    gptModel,
    lnPayment,
  },
  context
) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  await checkIfUserPaid({ context, lnPayment });

  const job = await context.entities.Job.findFirst({
    where: {
      id,
      user: { id: context.user.id },
    },
  });

  if (!job) {
    throw new HttpError(404, "Job not found");
  }

  const coverLetter = await generateCoverLetter(
    {
      jobId: id,
      title: job.title,
      content,
      description: job.description,
      isCompleteCoverLetter,
      includeWittyRemark,
      temperature,
      gptModel,
      lnPayment,
    },
    context
  );

  await context.entities.Job.update({
    where: {
      id,
    },
    data: {
      description,
      coverLetter: { connect: { id: coverLetter.id } },
    },
  });

  return coverLetter.id;
};

