export const deleteJob: DeleteJob<{ jobId: string }, { count: number }> = (
  { jobId },
  context
) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  if (!jobId) {
    throw new HttpError(401);
  }

  return context.entities.Job.deleteMany({
    where: {
      id: jobId,
      userId: context.user.id,
    },
  });
};

type UpdateUserArgs = Partial<
  Pick<User, "id" | "notifyPaymentExpires" | "gptModel">
>;
type UserWithoutPassword = Omit<User, "password">;

export const updateUser: UpdateUser<
  UpdateUserArgs,
  UserWithoutPassword
> = async ({ notifyPaymentExpires, gptModel }, context: any) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.User.update({
    where: {
      id: context.user.id,
    },
    data: {
      notifyPaymentExpires,
      gptModel,
    },
    select: {
      id: true,
      email: true,
      username: true,
      hasPaid: true,
      datePaid: true,
      notifyPaymentExpires: true,
      checkoutSessionId: true,
      stripeId: true,
      credits: true,
      gptModel: true,
      isUsingLn: true,
      subscriptionStatus: true,
      currentPlanType: true,
      currentPlanDuration: true,
      pendingPlanType: true,
      pendingPlanDuration: true,
    },
  });
};

