// In your existing operations file, update the createSubscription and upgradeSubscription functions:

export const createSubscription: StripePayment<
  SubscriptionPayload,
  StripePaymentResult
> = async ({ planType, duration }, context: any) => {
  if (!context.user || !context.user.email) {
    throw new HttpError(401, "User or email not found");
  }

  try {
    // Get or create customer
    const customer = await getOrCreateStripeCustomer(context.user.email);

    // Get or create price ID
    const priceId = await getOrCreatePriceId(planType, duration);

    // Create checkout session with updated success URL
    const session = await stripe.checkout.sessions.create({
      customer: customer.id,
      line_items: [
        {
          price: priceId,
          quantity: 1,
        },
      ],
      mode: "subscription",
      // Updated success URL to include session_id and plan info
      success_url: `${DOMAIN}/checkout/success?session_id={CHECKOUT_SESSION_ID}&plan=${planType}&duration=${duration}`,
      cancel_url: `${DOMAIN}/checkout/success?canceled=true`,
      automatic_tax: { enabled: true },
      customer_update: {
        address: "auto",
      },
      metadata: {
        userId: context.user.id,
        planType: planType,
        duration: duration,
      },
      subscription_data: {
        metadata: {
          userId: context.user.id,
          planType: planType,
          duration: duration,
        },
      },
    });

    // Update user with session and customer info
    await context.entities.User.update({
      where: { id: context.user.id },
      data: {
        checkoutSessionId: session.id,
        stripeId: customer.id,
        // Store the intended plan info (will be confirmed via success callback)
        pendingPlanType: planType,
        pendingPlanDuration: duration,
      },
    });

    return {
      sessionUrl: session.url,
      sessionId: session.id,
    };
  } catch (error: any) {
    console.error("Subscription creation error:", error);
    throw new HttpError(500, `Failed to create subscription: ${error.message}`);
  }
};

export const upgradeSubscription: StripePayment<
  SubscriptionPayload,
  StripePaymentResult
> = async ({ planType, duration }, context: any) => {
  if (!context.user || !context.user.email) {
    throw new HttpError(401, "User or email not found");
  }

  if (!context.user.stripeId) {
    throw new HttpError(400, "User does not have existing subscription");
  }

  try {
    // Get customer's current subscriptions
    const subscriptions = await stripe.subscriptions.list({
      customer: context.user.stripeId,
      status: "active",
      limit: 1,
    });

    if (subscriptions.data.length === 0) {
      throw new HttpError(400, "No active subscription found");
    }

    const currentSubscription = subscriptions.data[0];
    const newPriceId = await getOrCreatePriceId(planType, duration);

    // Create checkout session for upgrade with updated success URL
    const session = await stripe.checkout.sessions.create({
      customer: context.user.stripeId,
      line_items: [
        {
          price: newPriceId,
          quantity: 1,
        },
      ],
      mode: "subscription",
      // Updated success URL for upgrades
      success_url: `${DOMAIN}/checkout/success?session_id={CHECKOUT_SESSION_ID}&plan=${planType}&duration=${duration}&upgrade=true`,
      cancel_url: `${DOMAIN}/checkout/success?canceled=true`,
      automatic_tax: { enabled: true },
      subscription_data: {
        metadata: {
          userId: context.user.id,
          planType: planType,
          duration: duration,
          isUpgrade: "true",
          previousSubscriptionId: currentSubscription.id,
        },
      },
      metadata: {
        userId: context.user.id,
        planType: planType,
        duration: duration,
        isUpgrade: "true",
      },
    });

    // Update user with new session info
    await context.entities.User.update({
      where: { id: context.user.id },
      data: {
        checkoutSessionId: session.id,
        pendingPlanType: planType,
        pendingPlanDuration: duration,
      },
    });

    return {
      sessionUrl: session.url,
      sessionId: session.id,
    };
  } catch (error: any) {
    console.error("Subscription upgrade error:", error);
    throw new HttpError(
      500,
      `Failed to upgrade subscription: ${error.message}`
    );
  }
};
